static void dfs(int n, int k, int start, int *cur, int depth, int **res, int *size, int **cols) {
  if (depth == k) {
    res[*size] = (int *)malloc(sizeof(int) * k);
    for (int i = 0; i < k; i++) res[*size][i] = cur[i];
    (*cols)[*size] = k;
    (*size)++;
    return;
  }
  for (int i = start; i <= n; i++) {
    cur[depth] = i;
    dfs(n, k, i + 1, cur, depth + 1, res, size, cols);
  }
}

int **combine(int n, int k, int *returnSize, int **returnColumnSizes) {
  int **res = (int **)malloc(sizeof(int *) * 100000);
  *returnColumnSizes = (int *)malloc(sizeof(int) * 100000);
  int *cur = (int *)malloc(sizeof(int) * k);
  *returnSize = 0;
  dfs(n, k, 1, cur, 0, res, returnSize, returnColumnSizes);
  free(cur);
  return res;
}

class Solution {
  void dfs(int n, int k, int start, vector<int> &cur, vector<vector<int>> &res) {
    if ((int)cur.size() == k) {
      res.push_back(cur);
      return;
    }
    for (int i = start; i <= n; i++) {
      cur.push_back(i);
      dfs(n, k, i + 1, cur, res);
      cur.pop_back();
    }
  }

public:
  vector<vector<int>> combine(int n, int k) {
    vector<vector<int>> res;
    vector<int> cur;
    dfs(n, k, 1, cur, res);
    return res;
  }
};

func combine(n int, k int) [][]int {
	var res [][]int
	var cur []int
	var dfs func(start int)
	dfs = func(start int) {
		if len(cur) == k {
			tmp := make([]int, k)
			copy(tmp, cur)
			res = append(res, tmp)
			return
		}
		for i := start; i <= n; i++ {
			cur = append(cur, i)
			dfs(i + 1)
			cur = cur[:len(cur)-1]
		}
	}
	dfs(1)
	return res
}

class Solution {
  private void dfs(int n, int k, int start, List<Integer> cur, List<List<Integer>> res) {
    if (cur.size() == k) {
      res.add(new ArrayList<>(cur));
      return;
    }
    for (int i = start; i <= n; i++) {
      cur.add(i);
      dfs(n, k, i + 1, cur, res);
      cur.remove(cur.size() - 1);
    }
  }

  public List<List<Integer>> combine(int n, int k) {
    List<List<Integer>> res = new ArrayList<>();
    dfs(n, k, 1, new ArrayList<>(), res);
    return res;
  }
}

class Solution:
    def combine(self, n: int, k: int) -> List[List[int]]:
        res = []
        cur = []

        def dfs(start: int):
            if len(cur) == k:
                res.append(cur[:])
                return
            for i in range(start, n + 1):
                cur.append(i)
                dfs(i + 1)
                cur.pop()

        dfs(1)
        return res

impl Solution {
  pub fn combine(n: i32, k: i32) -> Vec<Vec<i32>> {
    fn dfs(n: i32, k: i32, start: i32, cur: &mut Vec<i32>, res: &mut Vec<Vec<i32>>) {
      if cur.len() as i32 == k {
        res.push(cur.clone());
        return;
      }
      for i in start..=n {
        cur.push(i);
        dfs(n, k, i + 1, cur, res);
        cur.pop();
      }
    }
    let mut res = vec![];
    let mut cur = vec![];
    dfs(n, k, 1, &mut cur, &mut res);
    res
  }
}

const combine = (n: number, k: number): number[][] => {
  const res: number[][] = [];
  const cur: number[] = [];

  const dfs = (start: number) => {
    if (cur.length === k) {
      res.push([...cur]);
      return;
    }
    for (let i = start; i <= n; i++) {
      cur.push(i);
      dfs(i + 1);
      cur.pop();
    }
  };

  dfs(1);
  return res;
};
